/* Shop preview. Shared catalog and browser bag; WooCommerce adapters replace these at conversion. */
(()=>{
'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const {products,brands,imageFrames}=window.UrbanCatalog;const find=id=>products.find(p=>p.id===id);
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reduced=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let cart=read('urban-preview-cart',[]).filter(v=>find(v.id)&&Number.isInteger(v.qty)&&v.qty>0).map(v=>({...v,qty:Math.min(99,v.qty)}));
let saved=read('urban-preview-wishlist',[]).filter(id=>find(id));let panel='',toastTimer,searchTimer,introDone=false;
const categories={hookahs:'Hookahs',bowls:'Bowls',heat:'Heat management',hoses:'Hoses & tips',care:'Tools & spares',charcoal:'Charcoal'};
const brandName=id=>brands.find(b=>b.id===id)?.name||id;
function art(p){const [x,y,w,h,sw,sh]=imageFrames[p.art];return `<span class="product-art art-${p.art}" role="img" aria-label="${p.name}"><svg class="catalog-photo" viewBox="${x} ${y} ${w} ${h}" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><image data-photo-src="assets/images/product-cutout-${p.art}.webp" width="${sw}" height="${sh}"/></svg></span>`;}
const photoObserver='IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;$$('image[data-photo-src]',entry.target).forEach(img=>{img.setAttribute('href',img.dataset.photoSrc);delete img.dataset.photoSrc;});photoObserver.unobserve(entry.target);}),{rootMargin:'600px 0px'}):null;
function hydrate(){ $$('image[data-photo-src]').forEach(img=>{if(photoObserver)photoObserver.observe(img.closest('.product-art'));else{img.setAttribute('href',img.dataset.photoSrc);delete img.dataset.photoSrc;}}); }
function card(p){const badge=p.badge==='Signature'?'Limited':p.badge==='The edit'?'Bestseller':p.badge?'New':'';return `<article class="product-card" data-id="${p.id}"><div class="product-image"><button class="product-picture" data-product="${p.id}" aria-label="View ${p.name}">${art(p)}</button>${badge?`<span class="product-badge badge-${badge.toLowerCase()}">${badge}</span>`:''}<button class="save-product ${saved.includes(p.id)?'is-saved':''}" data-save="${p.id}" aria-label="Save ${p.name}" aria-pressed="${saved.includes(p.id)}">${icon('heart')}</button><button class="quick-add" data-add="${p.id}" aria-label="Quick add ${p.name} to bag">Quick add ${icon('plus')}</button></div><div class="product-info"><div><p class="product-type">${p.label}</p><button class="product-name" data-product="${p.id}">${p.name}</button><p class="price">${money(p.price)}</p></div><button class="add-product" data-add="${p.id}" aria-label="Add ${p.name} to bag">${icon('plus')}</button></div></article>`;}
$$('.product-art').forEach(el=>{const index=Number(el.className.match(/art-(\d+)/)?.[1]);if(Number.isInteger(index))el.innerHTML=art(products.find(p=>p.art===index)).replace(/^<span[^>]*>|<\/span>$/g,'');});
function count(){const n=cart.reduce((sum,p)=>sum+p.qty,0);$$('.cart-count').forEach(el=>el.textContent=n);$('.bag-button').setAttribute('aria-label',`Open shopping bag, ${n} items`);}
function persist(){try{localStorage.setItem('urban-preview-cart',JSON.stringify(cart));localStorage.setItem('urban-preview-wishlist',JSON.stringify(saved));}catch{}count();}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
const drawer=$('#shop-dialog'),content=$('#content-dialog'),filterDialog=$('#filter-dialog');
function lock(){document.body.classList.toggle('is-locked',!!$('dialog[open]'));}
function open(dialog){if(dialog.open)return;[drawer,content,filterDialog].forEach(d=>{if(d.open)d.close();});dialog.showModal();lock();}
[drawer,content,filterDialog].forEach(d=>{d.addEventListener('close',lock);d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});});
const state={category:[],brand:[],min:0,max:20000,q:'',sort:'featured',new:false};
const allowedBrands=[...new Set(products.map(p=>p.brand).filter(Boolean)),...brands.map(b=>b.id)];
function readURL(){const query=new URLSearchParams(location.search);let cats=(query.get('category')||'').split(',');if(cats.includes('accessories'))cats=Object.keys(categories).filter(k=>k!=='hookahs');state.category=cats.filter(k=>categories[k]);state.brand=(query.get('brand')||'').split(',').filter(k=>allowedBrands.includes(k));state.min=Math.max(0,Math.min(20000,Number(query.get('min'))||0));state.max=Math.max(state.min,Math.min(20000,Number(query.get('max')??20000)||0));state.q=(query.get('q')||'').slice(0,200);state.sort=['featured','price-low','price-high','name'].includes(query.get('sort'))?query.get('sort'):'featured';state.new=query.get('new')==='1';syncInputs();}
function syncInputs(){ $$('[name="category"]').forEach(el=>el.checked=state.category.includes(el.value));$$('[name="brand"]').forEach(el=>el.checked=state.brand.includes(el.value));$('#price-min').value=state.min;$('#price-max').value=state.max;$('#price-range').value=state.max;$('#shop-search').value=state.q;$('#shop-sort').value=state.sort;$('[name="new"]').checked=state.new; }
function saveURL(){const query=new URLSearchParams();if(state.category.length)query.set('category',state.category.join(','));if(state.brand.length)query.set('brand',state.brand.join(','));if(state.min)query.set('min',state.min);if(state.max!==20000)query.set('max',state.max);if(state.q)query.set('q',state.q);if(state.sort!=='featured')query.set('sort',state.sort);if(state.new)query.set('new','1');history.replaceState(null,'',location.pathname+(query.size?'?'+query.toString():''));}
function matches(p,except=''){return(except==='category'||!state.category.length||state.category.includes(p.type))&&(except==='brand'||!state.brand.length||state.brand.includes(p.brand))&&p.price>=state.min&&p.price<=state.max&&(!state.new||['New','Compact'].includes(p.badge))&&`${p.name} ${p.label} ${p.brand} ${p.type}`.toLowerCase().includes(state.q.toLowerCase());}
let swapTween;
function render(animate=false){const list=products.filter(p=>matches(p));if(state.sort==='price-low')list.sort((a,b)=>a.price-b.price);if(state.sort==='price-high')list.sort((a,b)=>b.price-a.price);if(state.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));
 const title=state.brand.length===1?brandName(state.brand[0]):state.category.length===1?categories[state.category[0]]:'All products';$('#catalog-title').innerHTML=escape(title)+'<span class="punct">.</span>';$('#result-count').textContent=`${list.length} ${list.length===1?'product':'products'} in your edit`;
 const grid=$('#shop-products');swapTween?.kill();grid.innerHTML=list.map(card).join('');$('#shop-empty').hidden=!!list.length;$('.shop-end-note').hidden=!list.length;
 const referenceBrand=state.brand.length===1&&brands.find(b=>b.id===state.brand[0]);$('#empty-title').textContent=referenceBrand?`${referenceBrand.name}. Coming into the edit.`:'A different edit?';$('#empty-copy').textContent=referenceBrand?`No ${referenceBrand.name} products are listed in this preview yet. Browse the current hookahs and accessories while the brand catalog is prepared.`:'No products match these filters. Try a wider price range or clear a filter.';
 $$('[data-count-category]').forEach(el=>el.textContent=products.filter(p=>p.type===el.dataset.countCategory&&matches(p,'category')).length);$$('[data-count-brand]').forEach(el=>el.textContent=products.filter(p=>p.brand===el.dataset.countBrand&&matches(p,'brand')).length);
 const chips=[...state.category.map(v=>({key:'category',value:v,label:categories[v]})),...state.brand.map(v=>({key:'brand',value:v,label:brandName(v)}))];if(state.min||state.max!==20000)chips.push({key:'price',label:`${money(state.min)} – ${money(state.max)}`});if(state.q)chips.push({key:'q',label:`Search: ${state.q}`});if(state.new)chips.push({key:'new',label:'New arrivals'});
 $('#active-filters').innerHTML=chips.map(c=>`<button class="filter-chip" data-remove-filter="${c.key}" data-value="${escape(c.value||'')}" aria-label="Remove filter: ${escape(c.label)}">${escape(c.label)} ${icon('close')}</button>`).join('')+(chips.length?'<button class="filter-chip" data-clear>Clear all</button>':'');$('#filter-total').textContent=chips.length;$('#filter-apply').innerHTML=`Show ${list.length} ${list.length===1?'product':'products'} ${icon('arrow')}`;$('#price-note').textContent=`${money(state.min)} – ${money(state.max)}`;
 $$('.shop-category-tabs a').forEach(el=>{const category=new URL(el.href).searchParams.get('category');const active=category?state.category.length===1&&state.category[0]===category:!state.category.length;if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 hydrate();if(animate&&window.gsap&&!reduced())swapTween=gsap.fromTo([...grid.children],{y:14},{y:0,duration:.35,stagger:.025,ease:'power3.out',clearProps:'transform'});
}
function apply(){saveURL();render(true);}
function clear(){Object.assign(state,{category:[],brand:[],min:0,max:20000,q:'',sort:'featured',new:false});syncInputs();apply();}
$('#shop-filters').addEventListener('submit',e=>e.preventDefault());$('#shop-filters').addEventListener('change',e=>{const el=e.target;if(el.name==='category'||el.name==='brand')state[el.name]=$$(`[name="${el.name}"]:checked`).map(n=>n.value);if(el.name==='new')state.new=el.checked;if(el.name==='min'||el.name==='max'){state[el.name]=Math.min(20000,Math.max(0,Number(el.value)||0));if(state.min>state.max){if(el.name==='min')state.max=state.min;else state.min=state.max;}}syncInputs();apply();});
$('#price-range').addEventListener('input',e=>{state.max=Number(e.target.value);state.min=Math.min(state.min,state.max);syncInputs();apply();});
$('#shop-sort').addEventListener('change',e=>{state.sort=e.target.value;apply();});$('#shop-search').addEventListener('input',e=>{state.q=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(apply,180);});
$('#active-filters').addEventListener('click',e=>{const b=e.target.closest('[data-remove-filter]');if(!b)return;const key=b.dataset.removeFilter;if(key==='category'||key==='brand')state[key]=state[key].filter(v=>v!==b.dataset.value);else if(key==='price'){state.min=0;state.max=20000;}else state[key]=key==='q'?'':false;syncInputs();apply();});
window.addEventListener('popstate',()=>{readURL();render();});
const mobileMQ=matchMedia('(max-width:900px)');function moveFilters(){if(filterDialog.open)filterDialog.close();(mobileMQ.matches?$('#mobile-filter-content'):$('.shop-sidebar')).append($('#filter-panel'));lock();}moveFilters();mobileMQ.addEventListener('change',moveFilters);
$('#filter-open').addEventListener('click',()=>open(filterDialog));$('#mobile-filter-shortcut').addEventListener('click',()=>{if(mobileMQ.matches)open(filterDialog);});$('#filter-apply').addEventListener('click',()=>filterDialog.close());
function renderPanel(){const body=$('#drawer-body');if(panel==='cart'){body.innerHTML=cart.length?cart.map(row=>{const p=find(row.id);return `<div class="cart-item"><button class="cart-thumb" data-product="${p.id}" aria-label="View ${p.name}">${art(p)}</button><div><h3>${p.name}</h3><p>${money(p.price)}</p><div class="quantity-control"><button data-quantity="${p.id}" data-delta="-1" aria-label="Decrease ${p.name} quantity">−</button><span>${row.qty}</span><button data-quantity="${p.id}" data-delta="1" aria-label="Increase ${p.name} quantity">+</button></div></div><button class="remove-item" data-remove="${p.id}">Remove</button></div>`;}).join('')+`<div class="cart-summary"><span>Subtotal</span><strong>${money(cart.reduce((s,p)=>s+find(p.id).price*p.qty,0))}</strong></div><a class="view-full-cart" href="cart.html">View full bag ${icon('arrow')}</a><a class="button cart-checkout" href="checkout.html">Checkout ${icon('arrow')}</a><p class="cart-preview-note">Preview bag. No payment will be taken.</p>`:`<div class="empty-state"><h3>Your next favourite is waiting.</h3><p>Your bag is empty. Explore the edit below.</p><button class="button" data-browse>Keep exploring ${icon('arrow')}</button></div>`;}else{body.innerHTML=saved.length?`<div class="wishlist-products">${saved.map(id=>card(find(id))).join('')}</div>`:'<div class="empty-state"><h3>Your saved edit.</h3><p>Tap a heart to keep your favourites here.</p></div>';}hydrate();}
function openPanel(mode){if(mode==='search'){$('#shop-search').scrollIntoView({behavior:reduced()?'instant':'smooth',block:'center'});$('#shop-search').focus({preventScroll:true});return;}panel=mode;$('#drawer-title').textContent=mode==='cart'?'Your bag.':'Your saved edit.';renderPanel();open(drawer);}
function detail(id){if(id==='studio-black'){location.href='product.html';return;}const p=find(id);if(!p)return;$('#content-body').innerHTML=`<div class="product-detail"><div class="product-detail-image">${art(p)}</div><div><p class="eyebrow">${p.label}</p><h2 id="content-title">${p.name}</h2><p class="detail-price">${money(p.price)}</p><p class="detail-description">${p.description}</p><button class="button" data-add="${p.id}">Add to bag ${icon('bag')}</button><button class="text-link" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}" style="margin-top:20px">Save to wishlist ${icon('heart')}</button><small>Preview product and illustrative price. Confirm specifications with the live catalog.</small></div></div>`;hydrate();open(content);}
const info={contact:['Let’s talk.','Store contact channels will be connected before launch.'],shipping:['Shipping & delivery.','Delivery locations, costs and timelines will be published with the live store.'],returns:['Returns & refunds.','The store returns policy will be available before purchases open.'],orders:['Your orders.','Order tracking opens with your live account. This preview does not place orders.'],account:['Your account.','Account access opens with the live store. Your preview wishlist already works locally.'],privacy:['Your privacy.','Bag and wishlist choices stay in this browser. No newsletter email or order is submitted.'],terms:['Terms & conditions.','Real purchase terms will be published before checkout opens.'],age:['For adults only.','Urban Shisha is for adults 18+. Smoking is injurious to health.'],social:['Stay close to the edit.','Social channels will be connected before launch.'],faq:['Good to know.','This is a design preview. Filters, sorting, bag and wishlist work with a sample catalog; checkout opens with the live store.']};
function showInfo(key){if(key==='contact'){window.location.href='contact.html';return;}const config=window.URBAN_STORE||{};if(key==='social'&&/^https:\/\/(www\.)?instagram\.com\//.test(config.instagram||'')){window.open(config.instagram,'_blank','noopener,noreferrer');return;}const [title,text]=info[key]||info.faq;$('#content-body').innerHTML=`<article class="article-content"><p class="eyebrow">URBAN SHISHA / GOOD TO KNOW</p><h2 id="content-title">${title}</h2><p>${text}</p><button class="button" data-browse>Explore the edit ${icon('arrow')}</button></article>`;open(content);}
const addTimers=new WeakMap();document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.matches('.close-dialog')){b.closest('dialog').close();return;}if(b.hasAttribute('data-clear')){clear();return;}if(b.dataset.open){openPanel(b.dataset.open);return;}if(b.dataset.product){detail(b.dataset.product);return;}if(b.dataset.add){const p=find(b.dataset.add);if(!p)return;const row=cart.find(r=>r.id===p.id);if(row)row.qty=Math.min(99,row.qty+1);else cart.push({id:p.id,qty:1});persist();notify('Added to your setup');if(!b.dataset.restHtml)b.dataset.restHtml=b.innerHTML;clearTimeout(addTimers.get(b));b.innerHTML=icon('check');b.classList.add('is-added');addTimers.set(b,setTimeout(()=>{b.innerHTML=b.dataset.restHtml;b.classList.remove('is-added');},1300));if(window.gsap&&!reduced())gsap.fromTo('.bag-button',{scale:.9},{scale:1,duration:.4,ease:'back.out(2)',clearProps:'transform'});if(drawer.open&&panel==='cart')renderPanel();return;}if(b.dataset.save){const id=b.dataset.save;saved=saved.includes(id)?saved.filter(v=>v!==id):[...saved,id];persist();$$(`[data-save="${id}"]`).forEach(el=>{el.classList.toggle('is-saved',saved.includes(id));el.setAttribute('aria-pressed',saved.includes(id));});notify(saved.includes(id)?'Saved to your wishlist':'Removed from your wishlist');if(drawer.open&&panel==='wishlist')renderPanel();return;}if(b.dataset.quantity){const row=cart.find(r=>r.id===b.dataset.quantity);if(row)row.qty=Math.min(99,row.qty+Number(b.dataset.delta));cart=cart.filter(r=>r.qty>0);persist();renderPanel();return;}if(b.dataset.remove){cart=cart.filter(r=>r.id!==b.dataset.remove);persist();renderPanel();return;}if(b.dataset.category){state.category=[b.dataset.category];syncInputs();apply();$('#catalog').scrollIntoView({behavior:reduced()?'instant':'smooth'});return;}if(b.dataset.jumpBudget){state.max=6000;state.min=0;syncInputs();apply();$('#catalog').scrollIntoView({behavior:reduced()?'instant':'smooth'});return;}if(b.dataset.info){showInfo(b.dataset.info);return;}if(b.hasAttribute('data-preview-checkout')){notify('Checkout opens with the live store');return;}if(b.hasAttribute('data-browse')){[drawer,content].forEach(d=>d.close());$('#catalog').scrollIntoView({behavior:reduced()?'instant':'smooth'});return;}if(b.matches('.footer-toggle')&&matchMedia('(max-width:600px)').matches){const show=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',show);$('#'+b.getAttribute('aria-controls')).hidden=!show;}});
const mega=$('#category-menu'),megaToggle=$('#mega-toggle'),header=$('.site-header'),mobile=$('#mobile-nav'),mobileToggle=$('.mobile-toggle');let megaTimer;
function closeMega(){mega.hidden=true;megaToggle.setAttribute('aria-expanded','false');}function openMega(){mega.hidden=false;megaToggle.setAttribute('aria-expanded','true');hydrate();}function closeMenu(){mobile.hidden=true;mobileToggle.setAttribute('aria-expanded','false');mobileToggle.setAttribute('aria-label','Open navigation');mobileToggle.innerHTML=icon('menu');}
megaToggle.addEventListener('click',()=>mega.hidden?openMega():closeMega());megaToggle.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();openMega();$('a',mega).focus();}});megaToggle.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&!mobileMQ.matches){clearTimeout(megaTimer);openMega();}});mega.addEventListener('pointerenter',()=>clearTimeout(megaTimer));header.addEventListener('pointerleave',()=>megaTimer=setTimeout(closeMega,180));header.addEventListener('focusout',e=>{if(!header.contains(e.relatedTarget))closeMega();});document.addEventListener('click',e=>{if(!header.contains(e.target))closeMega();});
mobileToggle.addEventListener('click',()=>{const show=mobile.hidden;mobile.hidden=!show;mobileToggle.setAttribute('aria-expanded',show);mobileToggle.setAttribute('aria-label',show?'Close navigation':'Open navigation');mobileToggle.innerHTML=icon(show?'close':'menu');hydrate();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();if(!mega.hidden){closeMega();megaToggle.focus();}}});mobileMQ.addEventListener('change',()=>{closeMenu();closeMega();});
const footerMQ=matchMedia('(max-width:600px)');function footerLayout(){$$('.footer-toggle').forEach((b,i)=>{const show=!footerMQ.matches||i===0;b.setAttribute('aria-expanded',show);b.tabIndex=footerMQ.matches?0:-1;$('#'+b.getAttribute('aria-controls')).hidden=!show;});}footerLayout();footerMQ.addEventListener('change',footerLayout);$('#newsletter-form').addEventListener('submit',e=>{e.preventDefault();$('#newsletter-note').textContent='Preview only. Your email has not been submitted.';notify('Subscriptions open with the store');});$('#year').textContent=new Date().getFullYear();
function entrance(){if(introDone||reduced()||!window.gsap)return;introDone=true;gsap.from('.shop-intro h1,.shop-intro-copy>div>p,.shop-poster',{y:22,duration:.65,stagger:.08,ease:'power3.out',clearProps:'transform'});}
const age=$('#age-dialog');let accepted=false;try{accepted=localStorage.getItem('urban-preview-age')==='accepted';}catch{}age.addEventListener('cancel',e=>e.preventDefault());if(!accepted){age.showModal();lock();}else requestAnimationFrame(entrance);$('#age-accept').addEventListener('click',()=>{try{localStorage.setItem('urban-preview-age','accepted');}catch{}age.close();lock();entrance();});$('#age-decline').addEventListener('click',()=>{$('.age-actions').hidden=true;$('#age-declined').hidden=false;});
let scrollQueued=false;window.addEventListener('scroll',()=>{if(scrollQueued)return;scrollQueued=true;requestAnimationFrame(()=>{header.classList.toggle('is-scrolled',scrollY>30);scrollQueued=false;});},{passive:true});
window.addEventListener('pageshow',()=>{cart=read('urban-preview-cart',[]).filter(v=>find(v.id)&&v.qty>0);saved=read('urban-preview-wishlist',[]).filter(find);count();render();});
readURL();render();count();hydrate();
})();
